// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    keepMyEther c;
    function setUp() public { c = new keepMyEther(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount, address caller) public {
        vm.assume(depositAmount > 0 && withdrawAmount > 0);
        vm.assume(depositAmount >= withdrawAmount);
        vm.assume(caller != address(0) && caller != address(c) && caller.code.length == 0);
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        (bool success, ) = address(c).call{value: depositAmount}("");
        require(success, "Deposit failed");
        vm.prank(caller);
        c.withdraw();
        uint256 postBalance = c.balances(caller);
        assertTrue(postBalance == 0);
    }
}
